const items = $input.all();

const result = {
  projectContext: '',
  conOps: '',
  requirements: [],
  imageUrl: '',
  executionNumber: items[0].json.executionNumber
};

items.forEach(item => {
  const section = item.json.Section || '';
  const content = item.json.Content || '';

  if (section.toLowerCase().includes('project context')) {
    result.projectContext = content;
  }

  if (section.toLowerCase().includes('conops')) {
    result.conOps = content;
  }

  if (section.toLowerCase().includes('image')) {
    result.imageUrl = content;
  }

  if (section.match(/\b(FR|PR|ER|RR)\./i)) {
    result.requirements.push({
      requirementId: section,
      requirementText: content
    });
  }
});

return [{ json: result }];

